import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useQueryClient } from '@tanstack/react-query';
import { Globe, Clock, Tag } from 'lucide-react';
import { Input } from './ui/Input';
import { Button } from './ui/Button';
import { Card } from './ui/Card';
import { api } from '@/lib/api';

const formSchema = z.object({
  name: z.string().min(1, 'Name is required').max(100, 'Name must be 100 characters or less'),
  url: z
    .string()
    .min(1, 'URL is required')
    .url('Please enter a valid URL')
    .refine((val) => val.startsWith('https://'), {
      message: 'URL must start with https:// for secure probe validation',
    }),
  check_interval_s: z.coerce.number().pipe(z.union([z.literal(60), z.literal(300), z.literal(600)])),
});

type FormValues = z.infer<typeof formSchema>;

export function AddSiteForm() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const [submitError, setSubmitError] = useState<string | null>(null);

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      name: '',
      url: 'https://',
      check_interval_s: 60,
    },
  });

  const onSubmit = async (values: FormValues) => {
    try {
      setSubmitError(null);
      await api.createSite({
        name: values.name.trim(),
        url: values.url.trim(),
        check_interval_s: values.check_interval_s as 60 | 300 | 600,
      });

      await queryClient.invalidateQueries({ queryKey: ['sites'] });
      router.push('/dashboard');
    } catch (err: any) {
      setSubmitError(err.message || 'Failed to create monitored site');
    }
  };

  return (
    <Card className="max-w-xl mx-auto">
      <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
        {submitError && (
          <div className="p-3 text-xs bg-[#FF4D4F]/10 border border-[#FF4D4F]/30 text-[#FF4D4F] rounded-[6px]">
            {submitError}
          </div>
        )}

        <div>
          <label className="block text-xs font-medium text-[#8B949E] mb-1.5 flex items-center gap-1.5">
            <Tag className="h-3.5 w-3.5" /> Site / Service Name
          </label>
          <Input
            placeholder="e.g. My SaaS API"
            error={errors.name?.message}
            {...register('name')}
          />
        </div>

        <div>
          <label className="block text-xs font-medium text-[#8B949E] mb-1.5 flex items-center gap-1.5">
            <Globe className="h-3.5 w-3.5" /> HTTPS Endpoint URL
          </label>
          <Input
            placeholder="https://api.yourdomain.com/health"
            error={errors.url?.message}
            className="font-mono text-sm"
            {...register('url')}
          />
          <p className="text-[11px] text-[#8B949E] mt-1">
            PingWatch performs automated GET checks and verifies status codes 200–399.
          </p>
        </div>

        <div>
          <label className="block text-xs font-medium text-[#8B949E] mb-1.5 flex items-center gap-1.5">
            <Clock className="h-3.5 w-3.5" /> Monitoring Frequency
          </label>
          <select
            {...register('check_interval_s')}
            className="w-full px-3 py-2 bg-[#0D1117] border border-[#30363D] text-white text-sm rounded-[6px] focus:outline-none focus:border-[#00FF87] focus:ring-1 focus:ring-[#00FF87]"
          >
            <option value={60}>Every 1 minute (Recommended)</option>
            <option value={300}>Every 5 minutes</option>
            <option value={600}>Every 10 minutes</option>
          </select>
          {errors.check_interval_s && (
            <p className="text-xs text-[#FF4D4F] mt-1">{errors.check_interval_s.message}</p>
          )}
        </div>

        <div className="pt-2 flex items-center justify-end gap-3">
          <Button
            type="button"
            variant="secondary"
            onClick={() => router.push('/dashboard')}
          >
            Cancel
          </Button>
          <Button type="submit" variant="primary" isLoading={isSubmitting}>
            Start Monitoring
          </Button>
        </div>
      </form>
    </Card>
  );
}
